import json
with open('/app/resources/treasury_bulletin_1947_02.json', 'r') as f:
    data = json.load(f)

# Search for any data containing 1938
def search_dict(d, path=''):
    if isinstance(d, dict):
        for k, v in d.items():
            if '1938' in str(k):
                print(f'{path}.{k}: {v}')
            search_dict(v, f'{path}.{k}')
    elif isinstance(d, list):
        for i, item in enumerate(d):
            search_dict(item, f'{path}[{i}]')

search_dict(data)
