import json
with open('/app/resources/treasury_bulletin_1947_02.json', 'r') as f:
    data = json.load(f)

# Find the corporate bonds section
def find_bonds(d, path=''):
    if isinstance(d, dict):
        for k, v in d.items():
            if 'corporate' in str(k).lower() or 'bond' in str(k).lower():
                print(f'{path}.{k}')
            find_bonds(v, f'{path}.{k}')
    elif isinstance(d, list):
        for i, item in enumerate(d):
            find_bonds(item, f'{path}[{i}]')

find_bonds(data)
"
